-- Run only after inclusive_mrp_billing. Every fixture is rolled back.
-- Expected snapshots exercise TypeScript/PostgreSQL parity, not real food or money.
begin;
do $mrp_test$
declare fixture jsonb; doc jsonb; altered jsonb; order_id uuid; owner_id uuid; report jsonb;
  records_before integer; records_after integer; sample_id uuid; legacy jsonb; request_doc jsonb; q public.hpa_table_qr; rev bigint; request_id uuid; request_result jsonb;
begin
 select count(*) into records_before from public.hpa_orders;
 select m.user_id into owner_id from public.hpa_admin_memberships m join auth.users u on u.id=m.user_id
 where m.role='owner' and lower(u.email)='hotpizzaace@gmail.com' and u.email_confirmed_at is not null;
 if owner_id is null then raise exception 'test requires the verified development owner'; end if;
 for legacy in select data from public.hpa_orders loop
   if not public.hpa_order_tax_valid(legacy) then raise exception 'historical bill rejected'; end if;
 end loop;
 for fixture in select value from jsonb_array_elements($fixtures$[{"name":"water10","document":{"branchId":"barra","customer":{"name":"QA ONLY - DO NOT PREPARE","phone":"9876543210","address":"","locality":"","postalCode":"","landmark":"","instructions":""},"fulfillment":"pickup","paymentMethod":"cash","paymentStatus":"pending","status":"pending","items":[{"id":"qa-0","productId":"qa-mrp-0","name":"QA fixture","image":"/images/menu/photo-coming-soon.svg","options":[],"notes":"","unitPrice":1000,"quantity":1,"gstInclusive":{"rateBps":500,"code":"2201"}}],"subtotal":1000,"deliveryFee":0,"discount":0,"total":1000,"tax":{"supplier":{"businessName":"HOT PIZZA ACE","address":"ME346 Barra 2, Kanpur 208027","gstin":"09ANCPV1491R1Z3","fssaiNumber":"12721045000614","stateName":"Uttar Pradesh","stateCode":"09","sac":"996331","cgstRate":2.5,"sgstRate":2.5},"taxableValue":952,"cgst":24,"sgst":24,"total":48,"version":2,"includedTotal":48,"groups":[{"pricing":"inclusive","rateBps":500,"code":"2201","grossValue":1000,"deliveryFee":0,"discount":0,"taxableValue":952,"cgst":24,"sgst":24,"total":48}]},"coupon":""}},{"name":"water20","document":{"branchId":"barra","customer":{"name":"QA ONLY - DO NOT PREPARE","phone":"9876543210","address":"","locality":"","postalCode":"","landmark":"","instructions":""},"fulfillment":"pickup","paymentMethod":"cash","paymentStatus":"pending","status":"pending","items":[{"id":"qa-0","productId":"qa-mrp-0","name":"QA fixture","image":"/images/menu/photo-coming-soon.svg","options":[],"notes":"","unitPrice":2000,"quantity":1,"gstInclusive":{"rateBps":500,"code":"2201"}}],"subtotal":2000,"deliveryFee":0,"discount":0,"total":2000,"tax":{"supplier":{"businessName":"HOT PIZZA ACE","address":"ME346 Barra 2, Kanpur 208027","gstin":"09ANCPV1491R1Z3","fssaiNumber":"12721045000614","stateName":"Uttar Pradesh","stateCode":"09","sac":"996331","cgstRate":2.5,"sgstRate":2.5},"taxableValue":1904,"cgst":48,"sgst":48,"total":96,"version":2,"includedTotal":96,"groups":[{"pr