"id":"qa-1","productId":"qa-mrp-1","name":"QA fixture","image":"/images/menu/photo-coming-soon.svg","options":[],"notes":"","unitPrice":2000,"quantity":1,"gstInclusive":{"rateBps":500,"code":"2201"}}],"subtotal":12000,"deliveryFee":4900,"discount":1200,"total":16396,"tax":{"supplier":{"businessName":"HOT PIZZA ACE","address":"ME346 Barra 2, Kanpur 208027","gstin":"09ANCPV1491R1Z3","fssaiNumber":"12721045000614","stateName":"Uttar Pradesh","stateCode":"09","sac":"996331","cgstRate":2.5,"sgstRate":2.5},"taxableValue":15614,"cgst":391,"sgst":391,"total":782,"version":2,"includedTotal":86,"groups":[{"pricing":"exclusive","rateBps":500,"code":"996331","grossValue":10000,"deliveryFee":4900,"discount":1000,"taxableValue":13900,"cgst":348,"sgst":348,"total":696},{"pricing":"inclusive","rateBps":500,"code":"2201","grossValue":2000,"deliveryFee":0,"discount":200,"taxableValue":1714,"cgst":43,"sgst":43,"total":86}]},"coupon":"QA"}},{"name":"cold-drink","document":{"branchId":"barra","customer":{"name":"QA ONLY - DO NOT PREPARE","phone":"9876543210","address":"","locality":"","postalCode":"","landmark":"","instructions":""},"fulfillment":"pickup","paymentMethod":"cash","paymentStatus":"pending","status":"pending","items":[{"id":"qa-0","productId":"qa-mrp-0","name":"QA fixture","image":"/images/menu/photo-coming-soon.svg","options":[],"notes":"","unitPrice":4000,"quantity":1,"gstInclusive":{"rateBps":4000,"code":"2202"}}],"subtotal":4000,"deliveryFee":0,"discount":0,"total":4000,"tax":{"supplier":{"businessName":"HOT PIZZA ACE","address":"ME346 Barra 2, Kanpur 208027","gstin":"09ANCPV1491R1Z3","fssaiNumber":"12721045000614","stateName":"Uttar Pradesh","stateCode":"09","sac":"996331","cgstRate":2.5,"sgstRate":2.5},"taxableValue":2858,"cgst":571,"sgst":571,"total":1142,"version":2,"includedTotal":1142,"groups":[{"pricing":"inclusive","rateBps":4000,"code":"2202","grossValue":4000,"deliveryFee":0,"discount":0,"taxableValue":2858,"cgst":571,"sgst":571,"total":1142}]},"coupon":""}},{"name":"rates-and-remainder","document":{"branchId":"barra","customer":{"name":"QA ONLY - DO NOT PREPARE","phone":"9876543210","address":"","locality":"","postalCode":"","landmark":"","instructions":""},"fulfillment":"pickup","paymentMethod":"cash","paymentStatus":"pending","status":"pending","items":[{"id":"qa-0","productId":"qa-mrp-0","name":"QA fixture","image":"/images/menu/photo-coming-soon.svg","options":[],"notes":"","unitPrice":100,"quantity":1,"gstInclusive":{"rateBps":500,"code":"2202"}},{"id":"qa-1","productId":"qa-mrp-1","name":"QA fixture","image":"/images/menu/photo-coming-soon.svg","options":[],"notes":"","unitPrice":100,"quantity":1,"gstInclusive":{"rateBps":1800,"code":"2201"}},{"id":"qa-2","productId":"qa-mrp-2","name":"QA fixture","image":"/images/menu/photo-coming-soon.svg","options":[],"notes":"","unitPrice":100,"quantity":1,"gstInclusive":{"rateBps":1800,"code":"2202"}}],"subtotal":300,"deliveryFee":0,"discount":1,"total":299,"tax":{"supplier":{"businessName":"HOT PIZZA ACE","address":"ME346 Barra 2, Kanpur 208027","gstin":"09ANCPV1491R1Z3","fssaiNumber":"12721045000614","stateName":"Uttar Pradesh","stateCode":"09","sac":"996331","cgstRate":2.5,"sgstRate":2.5},"taxableValue":263,"cgst":18,"sgst":18,"total":36,"version":2,"includedTotal":36,"groups":[{"pricing":"inclusive","rateBps":1800,"code":"2201","grossValue":100,"deliveryFee":0,"discount":1,"taxableValue":83,"cgst":8,"sgst":8,"total":16},{"pricing":"inclusive","rateBps":1800,"code":"2202","grossValue":100,"deliveryFee":0,"discount":0,"taxableValue":84,"cgst":8,"sgst":8,"total":16},{"pricing":"inclusive","rateBps":500,"code":"2202","grossValue":100,"deliveryFee":0,"discount":0,"taxableValue":96,"cgst":2,"sgst":2,"total":4}]},"coupon":"QA"}},{"name":"paise-rounding","document":{"branchId":"barra","customer":{"name":"QA ONLY - DO NOT PREPARE","phone":"9876543210","address":"","locality":"","postalCode":"","landmark":"","instructions":""},"fulfillment":"pickup","paymentMethod":"cash","paymentStatus":"pending","status":"pending","items":[{"id":"qa-0","productId":"qa-mrp-0","name":"QA fixture","image":"/images/menu/photo-coming-soon.svg","options":[],"notes":"","unitPrice":21,"quantity":1,"gstInclusive":{"rateBps":500,"code":"2201"}},{"id":"qa-1","productId":"qa-mrp-1","name":"QA fixture","image":"/images/menu/photo-coming-soon.svg","options":[],"notes":"","unitPrice":19,"quantity":1,"gstInclusive":{"rateBps":1800,"code":"2202"}}],"subtotal":40,"deliveryFee":0,"discount":0,"total":40,"tax":{"supplier":{"businessName":"HOT PIZZA ACE","address":"ME346 Barra 2, Kanpur 208027","gstin":"09ANCPV1491R1Z3","fssaiNumber":"12721045000614","stateName":"Uttar Pradesh","stateCode":"09","sac":"996331","cgstRate":2.5,"sgstRate":2.5},"taxableValue":36,"cgst":2,"sgst":2,"total":4,"version":2,"includedTotal":4,"groups":[{"pricing":"inclusive","rateBps":1800,"code":"2202","grossValue":19,"deliveryFee":0,"discount":0,"taxableValue":17,"cgst":1,"sgst":1,"total":2},{"pricing":"inclusive","rateBps":500,"code":"2201","grossValue":21,"deliveryFee":0,"discount":0,"taxableValue":19,"cgst":1,"sgst":1,"total":2}]},"coupon":""}},{"name":"all-exclusive","document":{"branchId":"barra","customer":{"name":"QA ONLY - DO NOT PREPARE","phone":"9876543210","address":"","locality":"","postalCode":"","landmark":"","instructions":""},"fulfillment":"pickup","paymentMethod":"cash","paymentStatus":"pending","status":"pending","items":[{"id":"qa-0","productId":"qa-mrp-0","name":"QA fixture","image":"/images/menu/photo-coming-soon.svg","options":[],"notes":"","unitPrice":21900,"quantity":1}],"subtotal":21900,"deliveryFee":0,"discount":0,"total":22996,"tax":{"supplier":{"businessName":"HOT PIZZA ACE","address":"ME346 Barra 2, Kanpur 208027","gstin":"09ANCPV1491R1Z3","fssaiNumber":"12721045000614","stateName":"Uttar Pradesh","stateCode":"09","sac":"996331","cgstRate":2.5,"sgstRate":2.5},"taxableValue":21900,"cgst":548,"sgst":548,"total":1096},"coupon":""}}]$fixtures$::jsonb) loop
   doc:=fixture->'document'; if fixture->>'name'='water20' then request_doc:=doc; end if;
   if not public.hpa_order_tax_valid(doc) then raise exception 'valid fixture rejected: %',fixture->>'name'; end if;
   order_id:=gen_random_uuid(); sample_id:=order_id;
   doc:=doc||jsonb_build_object('id',order_id,'number','QA-MRP-'||order_id::text,'createdAt',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
   insert into public.hpa_orders(id,guest_session_hash,tracking_token_hash,idempotency_scope,idempotency_key,request_hash,data)
   values(order_id,repeat('a',64),repeat('b',64),'qa-mrp-rollback',order_id::text,repeat('c',64),doc);
   altered:=jsonb_set(doc,'{tax,total}',to_jsonb((doc->'tax'->>'total')::integer+1));
   if public.hpa_order_tax_valid(altered) then raise exception 'tampered tax total accepted'; end if;
   if doc->'tax'->>'version'='2' then
     altered:=jsonb_set(doc,'{tax,includedTotal}',to_jsonb((doc->'tax'->>'includedTotal')::integer+1));
     if public.hpa_order_tax_valid(altered) then raise exception 'tampered included tax accepted'; end if;
     altered:=jsonb_set(doc,'{items}',(select jsonb_agg(line-'gstInclusive') from jsonb_array_elements(doc->'items') line));
     if public.hpa_order_tax_valid(altered) then raise exception 'removed line classification accepted'; end if;
     altered:=jsonb_set(doc,'{tax,groups,0,discount}',to_jsonb((doc->'tax'->'groups'->0->>'discount')::integer+1));
     if public.hpa_order_tax_valid(altered) then raise exception 'tampered discount allocation accepted'; end if;
     altered:=jsonb_set(doc,'{total}',to_jsonb((doc->>'total')::integer+(doc->'tax'->>'includedTotal')::integer));
     if (doc->'tax'->>'includedTotal')::integer>0 and public.hpa_order_tax_valid(altered) then raise exception 'double charged GST accepted'; end if;
     begin
       update public.hpa_orders set data=jsonb_set(data,'{total}',to_jsonb((data->>'total')::integer+1)) where id=order_id;
       raise exception 'order constraint accepted invalid payable';
     exception when check_violation then null; end;
   end if;
 end loop;
 select * into q from public.hpa_table_qr where branch_id='barra' and ordering_scope='branch' and active=true limit 1;
 if not found then raise exception 'test requires the active development branch QR'; end if;
 select revision into rev from public.hpa_commerce_state where id=true;
 request_id:=gen_random_uuid();
 request_doc:=request_doc||jsonb_build_object('branchId',q.branch_id,'tableLabel',q.table_label,'customerName','QA rollback only','customerPhone','9876543210','notes','QA ONLY - DO NOT PREPARE','selections',jsonb_build_array(jsonb_build_object('id','qa-0','productId','hpa-water-bottle-20','quantity',1,'toppingIds','[]'::jsonb,'notes','')));
 request_doc:=jsonb_set(request_doc,'{tax,supplier}',(select data->'settings'->'billing' from public.hpa_branches where id=q.branch_id));
 request_result:=public.hpa_create_table_request(q.token_hash,repeat('d',64),gen_random_uuid(),repeat('e',64),rev,request_id,request_doc);
 if (request_result->'request'->>'total')::integer<>2000 then raise exception 'QR preview added extra GST to MRP'; end if;
 begin
   update public.hpa_table_requests set data=jsonb_set(data,'{total}','2001'::jsonb) where id=request_id;
   raise exception 'QR request constraint accepted a double-charge';
 exception when check_violation then null; end;
 if not public.hpa_gst_inclusive_valid('{"rateBps":500,"code":"2201"}')
   or public.hpa_gst_inclusive_valid('{"rateBps":0,"code":"2201"}')
   or public.hpa_gst_inclusive_valid('{"rateBps":501,"code":"2201"}')
   or public.hpa_gst_inclusive_valid('{"rateBps":500,"code":"bad"}')
   or public.hpa_gst_inclusive_valid('{"rateBps":500,"code":"2201","exempt":true}')
 then raise exception 'inclusive classification validation failed'; end if;
 report:=public.hpa_sales_report_snapshot(owner_id,'barra',
   date_trunc('day',now() at time zone 'Asia/Kolkata') at time zone 'Asia/Kolkata',
   (date_trunc('day',now() at time zone 'Asia/Kolkata')+interval '1 day') at time zone 'Asia/Kolkata');
 if not exists(select 1 from jsonb_array_elements(report->'orders') r where r->>'id'=sample_id::text) then raise exception 'report lost fixture'; end if;
 if not exists(select 1 from jsonb_array_elements(report->'orders') r where r->'tax'->>'version'='2' and r->'tax' ?& array['groups','includedTotal','taxableValue']) then raise exception 'report stripped versioned tax groups'; end if;
 if exists(select 1 from jsonb_array_elements(report->'orders') r where r ? 'customer' or r ? 'items') then raise exception 'report exposed customer or item data'; end if;
 if has_function_privilege('anon','public.hpa_order_tax_valid(jsonb)','EXECUTE') or has_function_privilege('authenticated','public.hpa_order_tax_valid(jsonb)','EXECUTE') then raise exception 'validation RPC exposed to client'; end if;
 select count(*) into records_after from public.hpa_orders;
 if records_after<>records_before+8 then raise exception 'unexpected fixture order count'; end if;
end $mrp_test$;
rollback;
